-- Arathi Highlands: creature abilities
-- Most of the zone's creatures (the Boulderfist and Witherbark trolls and ogres, the Syndicate, the Forsaken and Stromgarde of the
-- Highlands, the Hammerfall guards, the wildlife) had no AI or ran classic rows. Arathi is the Cataclysm revamp, so port their
-- abilities from the Cataclysm data, and from the classic data where Cataclysm has none, keeping the scripts already in place.
-- The Syndicate Thieves and the guards, which no reference scripts, cast their sniffed spells (creature_template spell1-8).

SET @ENTRIES := '2553,2555,2557,2559,2560,2566,2570,2572,2574,2581,2582,2583,2585,2591,2592,2595,2596,2599,2602,2605,2606,2612,2618,2619,2621,2713,2733,2761,2773,2779,2783,2793,10696,15126,15128,15130,19905,42879';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '24477,41295,42090,51819,51899';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
